const create=(list,container,side)=>list.forEach(t=>{let b=document.createElement('button');b.className='team-option'+((side==='home'?home:away)===t?' selected':'');b.textContent=t.name;b.onclick=()=>{if(side==='home')home=t;else away=t;renderTeamPanel(type)};$(container).appendChild(b)});
create(clubs,'#homeTeams','home');create(nations,'#homeTeams','home');create(clubs,'#awayTeams','away');create(nations,'#awayTeams','away');
$$('.mode-chip').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$$('.mode-chip').forEach(c=>c.classList.toggle('selected',c===b))});$('#startMatch').onclick=()=>{if(type==='world'){if(clubs.includes(home))home=teams[15];if(clubs.includes(away))away=teams[16]}if(type==='training'){away=teams[17]}if(type==='career'){mode='career'}else if(type==='tournament')mode='tournament';else if(type==='world')mode='world';else if(type==='training')mode='training';panel.classList.add('hidden');startGame()};}
