 if(!carrier){if(ball.owner===undefined&&dist(ball,human)<40){ball.owner=0;ball.carrier=human.index;carrier=human}else if(ball.owner===0)carrier=own[ball.carrier];else return}
 const sign=1;let angle=0;const dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0)+joy.x,dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0)+joy.y;if(Math.hypot(dx,dy)>.25)angle=Math.atan2(dy,dx);else angle=Math.atan2(327-carrier.y,sign*(Math.random()*.14));
 if(type==='pass'||type==='long'){const receiver=own.filter(p=>p!==carrier).sort((a,b)=>{let da=dist(a,carrier),db=dist(b,carrier);return da+(a.x<carrier.x?90:0)-db-(b.x<carrier.x?90:0)})[0];if(receiver&&type==='pass'){angle=Math.atan2(receiver.y-carrier.y,receiver.x-carrier.x);ball.x=carrier.x;ball.y=carrier.y;ball.owner=undefined;ball.carrier=undefined;ball.vx=Math.cos(angle)*245;ball.vy=Math.sin(angle)*245;say('pass')}else{ball.x=carrier.x;ball.y=carrier.y;ball.owner=undefined;ball.carrier=undefined;ball.vx=Math.cos(angle)*350;ball.vy=Math.sin(angle)*350;say('pass')}G.actionLock=.32}
