window.addEventListener('keydown',e=>{const key=e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Shift'].includes(key))e.preventDefault();if(key==='Escape'&&G){matchTogglePause();return}if(!G||G.paused)return;keys[key]=true;if(key==='j'||key==='J')keys.j=true;if(key==='k'||key==='K'||key===' ')keys.k=true;if(key==='l'||key==='L')keys.l=true;if(key==='e'||key==='E')keys.e=true;if(key==='q'||key==='Q')keys.q=true});
window.addEventListener('keyup',e=>{keys[e.key]=false;if(e.key==='Shift')keys.Shift=false});
const joyEl=$('#joystick'),knob=$('.joy-knob');let joyPointer=null;
function joyMove(e){if(joyPointer!==e.pointerId)return;const r=joyEl.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let x=(e.clientX-cx)/(r.width*.34),y=(e.clientY-cy)/(r.height*.34),m=Math.hypot(x,y);if(m>1){x/=m;y/=m}joy.x=x;joy.y=y;knob.style.transform=`translate(${x*28}px,${y*28}px)`}
joyEl.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joyEl.setPointerCapture(e.pointerId);joyMove(e)});joyEl.addEventListener('pointermove',joyMove);function releaseJoy(e){if(joyPointer===e.pointerId){joyPointer=null;joy.x=joy.y=0;knob.style.transform=''}}joyEl.addEventListener('pointerup',releaseJoy);joyEl.addEventListener('pointercancel',releaseJoy);
$$('.touch-actions button').forEach(button=>{const act=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.classList.add('active');if(act==='sprint')keys.sprint=true;else if(act==='switch')switchPlayer();else action(act)});const release=()=>{button.classList.remove('active');if(act==='sprint')keys.sprint=false};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('pointerleave',release)});
